import { expect, test } from "../../fixtures";

test.describe("sign in", () => {
  test("current user is returned for a valid session", { tag: "@AUTH-04" }, async ({ apiAs }) => {
    // Arrange: a signed-in member session
    const member = await apiAs("member");

    // Act
    const res = await member.get("/api/me");

    // Assert
    expect(res.status(), await res.text()).toBe(200);
    const profile = await res.json();
    expect(profile.email, JSON.stringify(profile)).toBe("member@northwind.test");
    expect(profile.role, JSON.stringify(profile)).toBe("member");
    expect(profile.tenant.name, JSON.stringify(profile)).toBe("Northwind Supply");
  });
});
